// ── Twenty CRM: flatten leads + nested activities ─────────────────────────
// Input : HTTP Request node output ({ data: { leads: [...] }, pageInfo })
// Output: one n8n item per lead, flattened and formatted
// Requires depth=1 on the request so activities/assignee are expanded.

const MICROS = 1_000_000;
const ACTIVITY_LIMIT = $('Variables').first().json.activities_limit;   // recent activities kept per lead
const CRM_BASE = $('Variables').first().json.crm_base_url;

// Handles both shapes: the wrapped list response, and a single lead item.
const rows = $input.all().flatMap((i) => {
  const j = i.json ?? {};
  if (Array.isArray(j?.data?.leads)) return j.data.leads;
  if (j?.data?.lead) return [j.data.lead];
  return j?.id ? [j] : [];
});

const titleCase = (s) =>
  !s ? null : String(s).toLowerCase().split('_')
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');

const inr = (n) =>
  new Intl.NumberFormat('en-IN', { maximumFractionDigits: 0 }).format(n);

const money = (dv) => {
  if (!dv?.amountMicros) return { amount: 0, currency: 'INR', formatted: '—' };
  const amount = Number(dv.amountMicros) / MICROS;
  const currency = dv.currencyCode || 'INR';
  return {
    amount,
    currency,
    formatted: currency === 'INR'
      ? `₹${inr(amount)}`
      : new Intl.NumberFormat('en-IN', {
          style: 'currency', currency, maximumFractionDigits: 0,
        }).format(amount),
  };
};

const phoneOf = (p) =>
  p?.primaryPhoneNumber
    ? `${p.primaryPhoneCallingCode ?? ''}${p.primaryPhoneNumber}`.replace(/\s+/g, '')
    : null;

const fullName = (n) =>
  n ? [n.firstName, n.lastName].filter(Boolean).join(' ') || null : null;

// activityDate may be a bare date or a full timestamp — fall back to createdAt,
// and use createdAt as the tiebreaker so same-day rows keep a stable order.
const when = (a) => {
  const t = Date.parse(a?.activityDate ?? '');
  return Number.isNaN(t) ? Date.parse(a?.createdAt ?? '') || 0 : t;
};

const daysBetween = (ms) =>
  ms ? Math.floor((Date.now() - ms) / 86_400_000) : null;

return rows.map((l) => {
  const deal = money(l.dealValue);
  const primaryPhone = phoneOf(l.phone);

  const acts = (l.activities ?? [])
    .filter((a) => !a.deletedAt)
    .sort((a, b) => (when(b) - when(a))
      || ((Date.parse(b.createdAt ?? '') || 0) - (Date.parse(a.createdAt ?? '') || 0)));

  const last = acts[0] ?? null;
  const lastMs = last ? when(last) : null;

  // counts per activity type, e.g. { Whatsapp: 12, Call: 3 }
  const byType = acts.reduce((acc, a) => {
    const k = titleCase(a.activityType) ?? 'Other';
    acc[k] = (acc[k] ?? 0) + 1;
    return acc;
  }, {});

  const recent = acts.slice(0, ACTIVITY_LIMIT).map((a) => ({
    id: a.id,
    type: titleCase(a.activityType),
    typeRaw: a.activityType ?? null,
    date: a.activityDate ?? a.createdAt ?? null,
    duration: a.duration ?? null,
    entryType: titleCase(a.entryType),
    sentBy: a.sentBy ?? null,
    summary: a.summary?.markdown?.trim() || a.name || null,
    waMessageId: a.waMessageId ?? null,
  }));

  // compact plain-text history, ready for an LLM prompt or a digest message
  const history = recent.length
    ? recent.map((a) => {
        const d = a.date ? String(a.date).slice(0, 10) : '—';
        const dur = a.duration ? ` (${a.duration}m)` : '';
        const who = a.sentBy ? ` by ${a.sentBy}` : '';
        return `• ${d} — ${a.type ?? 'Activity'}${dur}${who}: ${a.summary ?? 'No summary'}`;
      }).join('\n')
    : 'No activities logged yet.';

  return {
    json: {
      // ── identity ──
      id: l.id,
      name: l.name || l.companyName || 'Unnamed lead',
      companyName: l.companyName ?? null,
      email: l.email?.primaryEmail || null,
      phone: primaryPhone,
      whatsapp: l.whatsappNumber || primaryPhone,

      // ── pipeline ──
      stage: titleCase(l.stage),
      stageRaw: l.stage ?? null,
      source: titleCase(l.source),
      businessType: titleCase(l.businessType),
      chancesOfBuying: titleCase(l.chancesOfBuying),
      chancesRaw: l.chancesOfBuying ?? null,
      dealValue: deal.amount,
      dealValueFormatted: deal.formatted,
      currency: deal.currency,

      // ── follow-up ──
      takeFollowUp: l.takeFollowUp ?? null,
      followUpsDone: l.followUpsDone ?? 0,
      followUpOutcome: titleCase(l.followUpOutcome),
      nextFollowUpDate: l.nextFollowUpDate ?? null,
      nextAction: l.nextAction || 'No action set',

      // ── relations (need depth=1) ──
      assignee: fullName(l.assignee?.name),
      assigneeId: l.assigneeId ?? null,
      assignedCompany: l.assignedCompany?.name ?? null,
      linkedPackage: l.linkedPackage?.name ?? null,

      // ── activities ──
      activityCount: acts.length,
      activityCountByType: byType,
      lastActivityType: last ? titleCase(last.activityType) : null,
      lastActivityDate: last?.activityDate ?? last?.createdAt ?? null,
      lastActivitySummary: last?.summary?.markdown?.trim() || last?.name || null,
      daysSinceLastActivity: daysBetween(lastMs),
      activities: recent,
      activityHistory: history,

      // ── misc ──
      notes: l.notes?.markdown?.trim() || null,
      createdAt: l.createdAt ?? null,
      crmUrl: `${CRM_BASE}/object/lead/${l.id}`,
    },
  };
});

