// Follow-up ladder: given the CURRENT followUpsDone, compute the state
// AFTER the follow-up you just sent.
//   1,2 -> +3 days   3 -> +14 days   4 -> +30 days   5 -> stop
const LADDER = { 1: 1, 2: 2, 3: 7, 4: 14 };
const MAX_FOLLOW_UPS = 5;

const iso = (d) => d.toISOString().slice(0, 10);
const addDays = (n) => {
  const d = new Date();
  d.setDate(d.getDate() + n);
  return iso(d);
};

return $input.all().map((item) => {
  const l = item.json;
  const next = (l.followUpsDone ?? 0) + 1;   // the one just sent

  const body = { followUpsDone: next };
  let action;

  if (next >= MAX_FOLLOW_UPS) {
    body.takeFollowUp = false;
    action = 'exhausted';
  } else {
    body.takeFollowUp = true;
    body.nextFollowUpDate = addDays(LADDER[next] ?? 3);
    action = 'scheduled';
  }

  return {
    json: {
      leadId: l.id,
      name: l.name,
      whatsapp: l.whatsapp,
      previousCount: l.followUpsDone ?? 0,
      followUpNumber: next,
      action,
      daysAdded: next >= MAX_FOLLOW_UPS ? null : (LADDER[next] ?? 3),
      updateBody: body,
      crmUrl: `https://crm.lakshitukani.com/object/lead/${l.id}`,
    },
  };
});

