// n8n Code node — "Run Once for Each Item" mode (this runs per-lead, inside
// the Loop Over Items). If you switch to "Run Once for All Items", swap
// $input.item for $input.all()[i] inside a loop instead.

// === ADJUST THESE TWO LINES TO MATCH YOUR FLOW ===
// The raw ChatSyncs API response for this lead's conversation (the
// [{ status, message, nextOffset }] shape from the sample you shared).
const chatSyncsResponse = $input.item.json;

// The lead's previously-known last message time from the CRM.
// Undefined/null/empty string = new lead, no prior value to compare against.
// If this lives on a different node in your flow, change this to e.g.
// $('Get Lead From CRM').item.json.lastMsgTime
const lastMsgTime = $input.item.json.lastMsgTime;

// ---------------------------------------------------------------------

function safeParse(str) {
  try {
    return JSON.parse(str);
  } catch (e) {
    return null;
  }
}

// Turns a ChatSyncs "conversation_time" string (or any date-ish string)
// into a real Date object so comparisons are safe regardless of exact
// string format differences between ChatSyncs and what's stored in the CRM.
function toDate(str) {
  if (!str) return null;
  const iso = str.includes('T') ? str : str.replace(' ', 'T');
  const d = new Date(iso);
  return isNaN(d.getTime()) ? null : d;
}

// Pulls a single human-readable line of text out of one raw message entry.
// Returns null for entries with nothing worth showing (deleted messages,
// unsupported types, unparseable content) so the caller can skip them.
// Meeting confirmation/reminder templates repeat the same long, emoji-heavy
// boilerplate on every confirmation and every reminder — and re-paste the
// lead's own earlier message back as "Agenda", which is pure duplication.
// Collapse them to one short line: same information, far fewer tokens.
// Returns null if the template's name doesn't look meeting-related, or if
// none of the expected labels were found (falls back to the raw body then).
function simplifyMeetingTemplate(parsed) {
  if (!/meeting/i.test(parsed.name || '')) return null;

  const body = parsed.components?.find((c) => c.type === 'body')?.text || '';
  const name = body.match(/Hi ([^,]+),/)?.[1]?.trim();
  const date = body.match(/(?:Date|Today):\s*([^\n]+)/)?.[1]?.trim();
  const time = body.match(/\bTime:\s*([^\n]+)/)?.[1]?.trim();
  const title = body.match(/Meeting Title:\s*([^\n]+)/)?.[1]?.trim();
  const startsIn = body.match(/starts in ([^.\n]+)/i)?.[1]?.trim();

  if (!name && !date && !time && !title && !startsIn) return null;

  const who = name ? ` for ${name}` : '';
  const when = startsIn
    ? `starts in ${startsIn}${date ? ` (${date})` : ''}`
    : [date, time].filter(Boolean).join(' at ');
  const what = title ? ` — ${title}` : '';
  const kind = startsIn ? 'Meeting reminder sent' : 'Meeting confirmed';

  return `[${kind}${who}: ${when}${what}]`;
}

function extractText(entry) {
  const parsed = safeParse(entry.message_content);
  if (!parsed) return null;

  // Shape 1: bot-sent template message — no "object" wrapper, has "components"
  if (parsed.components) {
    const meetingSummary = simplifyMeetingTemplate(parsed);
    if (meetingSummary) return meetingSummary;
    const body = parsed.components.find((c) => c.type === 'body');
    return body ? body.text : '[template message]';
  }

  const value = parsed.entry?.[0]?.changes?.[0]?.value;
  if (!value) return null;

  // Shape 2: bot's own plain-text sends
  if (value.message_echoes?.length) {
    return value.message_echoes[0].text?.body || null;
  }

  // Shape 3: user-sent messages — branch on type
  const msg = value.messages?.[0];
  if (!msg) return null;

  switch (msg.type) {
    case 'text':
      return msg.text?.body || null;
    case 'image':
      return msg.image?.caption ? msg.image.caption : '[image, no caption]';
    case 'document':
      return `[document: ${msg.document?.filename || 'file'}]`;
    case 'button':
      return `[tapped button: "${msg.button?.text || msg.button?.payload || ''}"]`;
    case 'revoke':
    case 'unsupported':
      return null; // nothing meaningful to show
    default:
      return `[${msg.type} message]`;
  }
}

// ---------------------------------------------------------------------

const rawMessages = Array.isArray(chatSyncsResponse)
  ? chatSyncsResponse[0]?.message || []
  : chatSyncsResponse?.message || [];

const lastMsgDate = toDate(lastMsgTime);

const lines = [];
let latestSeen = null;

for (const entry of rawMessages.slice().sort((a, b) =>
  a.conversation_time.localeCompare(b.conversation_time)
)) {
  const entryDate = toDate(entry.conversation_time);
  if (entryDate && (!latestSeen || entryDate > latestSeen)) {
    latestSeen = entryDate;
  }

  // The one line to flip if you actually meant "up to" instead of "after":
  // change `<=` to `>` below.
  if (lastMsgDate && entryDate && entryDate <= lastMsgDate) continue;

  const text = extractText(entry);
  if (text === null) continue;

  const speaker = entry.sender === 'user' ? 'Lead' : 'Business';
  lines.push(`[${entry.conversation_time}] ${speaker}: ${text}`);
}

return [
  {
    json: {
      conversation: lines.join('\n'),
      messageCount: lines.length,
      latestMessageTime: latestSeen ? latestSeen.toISOString() : null,
    },
  },
];

// n8n Code node — "Run Once for Each Item"
// Normalizes a Twenty CRM lead-lookup response into a flat shape ready for
// the IF branch (new vs existing) and for direct use as AI Agent variables.

// === ADJUST IF YOUR HTTP NODE WRAPS THE RESPONSE DIFFERENTLY ===
const response = $input.item.json;
const leads = Array.isArray(response)
  ? response[0]?.data?.leads
  : response?.data?.leads;

// Treat a soft-deleted record as "not found" — you don't want this workflow
// silently updating/reviving a lead someone deliberately deleted.
const lead = leads?.length && !leads[0].deletedAt ? leads[0] : null;

if (!lead) {
  // No usable match — new-lead path. Nothing to render for the update agent.
  return [{ json: { isNewLead: true, leadId: null } }];
}

// --- Helpers ---
function phoneToString(phone) {
  // whatsappNumber is the more reliable match key against ChatSyncs' wa_id —
  // it already includes the calling code digits the way ChatSyncs sends them.
  // primaryPhoneNumber does NOT (it's stored separately from the calling
  // code), so don't use this for matching — it's here for display only.
  if (!phone?.primaryPhoneNumber) return null;
  return `${phone.primaryPhoneCallingCode || ''}${phone.primaryPhoneNumber}`;
}

// --- Normalize ---
return [
  {
    json: {
      isNewLead: false,
      leadId: lead.id,
      name: lead.name || null,
      phone: phoneToString(lead.phone),
      whatsappNumber: lead.whatsappNumber || null,
      lastMsgTime: lead.lastMsgTime || null, // pre-comparison, already-stored value

      // Named to match the AI Agent prompts' variables exactly — no
      // relabeling needed when you wire this straight into the Set node
      // (or reference it directly) feeding the Existing Lead Update
      // Classifier.
      CURRENT_STAGE: lead.stage || 'NEW',
      CURRENT_CHANCES_OF_BUYING: lead.chancesOfBuying || null,
      CURRENT_NEXT_ACTION: lead.nextAction || null,
      CURRENT_NEXT_FOLLOW_UP_DATE: lead.nextFollowUpDate || null,
      CURRENT_NOTES: lead.notes?.markdown || '',
      CURRENT_TAKE_FOLLOW_UP: lead.takeFollowUp ?? true,

      // Deliberately NOT rendered: followUpsDone, followUpOutcome — you
      // confirmed this workflow doesn't touch either.
    },
  },
];

