// n8n Code node — "Run Once for Each Item"
// Replaces "Does the last message time match?" (IF node). Decides whether
// this lead has genuinely new conversation to process, handling the edge
// cases explicitly instead of one compound condition that can throw.

const crmLastMsgTimeRaw = $('Render Lead Info').item.json.lastMsgTime;
const chatSyncsTimeRaw = $('Render with Country Information1').item.json.last_message_time;

function truncateToMinute(date) {
  const d = new Date(date);
  d.setSeconds(0, 0);
  return d;
}

// Case 1: no stored lastMsgTime yet. This is a newly added column — most
// existing leads simply predate it. Absence here doesn't mean "nothing
// changed", it means "we've never checked this lead under the new system",
// so always proceed.
if (!crmLastMsgTimeRaw) {
  return [{
    json: {
      ...$input.item.json,
      shouldProceedWithUpdate: true,
      skipReason: null,
      debugReason: 'no_stored_lastMsgTime',
    },
  }];
}

// Case 2: nothing to compare against on the ChatSyncs side. Can't tell if
// anything is new, so don't act — this shouldn't normally happen at this
// point in the flow, but it's cheap to guard against.
if (!chatSyncsTimeRaw) {
  return [{
    json: {
      ...$input.item.json,
      shouldProceedWithUpdate: false,
      skipReason: 'no_chatsyncs_time',
      debugReason: 'no_chatsyncs_time',
    },
  }];
}

// CRM value is a proper ISO timestamp (UTC) — parses directly.
const crmDate = new Date(crmLastMsgTimeRaw);

// ChatSyncs value is a plain "YYYY-MM-DD HH:mm[:ss]" string with no
// timezone marker — that's IST. Append the IST offset explicitly so it
// resolves to the correct real-world instant, not UTC or whatever timezone
// the n8n server happens to run in.
const chatSyncsIso = chatSyncsTimeRaw.trim().replace(' ', 'T') + '+05:30';
const chatSyncsDate = new Date(chatSyncsIso);

if (isNaN(crmDate.getTime()) || isNaN(chatSyncsDate.getTime())) {
  // Couldn't parse one side. Default to proceeding rather than silently
  // dropping a lead that might genuinely have new activity — a wasted
  // AI call is cheap, a missed follow-up isn't. Flip this default if you'd
  // rather fail closed instead.
  return [{
    json: {
      ...$input.item.json,
      shouldProceedWithUpdate: true,
      skipReason: null,
      debugReason: 'unparseable_date_defaulted_to_proceed',
    },
  }];
}

// Compare at minute precision on both sides, not full precision. The CRM
// value is written with seconds already dropped, so comparing it against a
// full-precision ChatSyncs timestamp would make every run look like "new
// activity" purely from that truncation, even when nothing happened.
const crmMinute = truncateToMinute(crmDate);
const chatSyncsMinute = truncateToMinute(chatSyncsDate);

const shouldProceedWithUpdate = chatSyncsMinute.getTime() > crmMinute.getTime();

return [{
  json: {
    ...$input.item.json,
    shouldProceedWithUpdate,
    skipReason: shouldProceedWithUpdate ? null : 'no_new_message_since_last_check',
    debugReason: shouldProceedWithUpdate ? 'new_message_detected' : 'timestamps_match_or_stale',
  },
}];

// n8n Code node — "Run Once for Each Item"
// Safety net between the AI Agent and the Twenty CRM update/create call.
// Catches invalid or placeholder dates (like "0000-00-00") regardless of
// what the prompt says — this should never be the only line of defense,
// but it's the one that can't be talked out of running.

// === ADJUST IF YOUR AI AGENT NODE NESTS ITS OUTPUT DIFFERENTLY ===
// e.g. some Structured Output setups put this under .output instead.
const agentOutput = $input.item.json;

function isRealDate(str) {
  if (typeof str !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(str)) return false;
  const [y, m, day] = str.split('-').map(Number);
  const d = new Date(Date.UTC(y, m - 1, day));
  // Guards against JS's lenient date rollover (e.g. Feb 30 silently
  // becoming Mar 2 instead of being rejected) by checking the parsed
  // value round-trips to the exact same year/month/day.
  return (
    !isNaN(d.getTime()) &&
    d.getUTCFullYear() === y &&
    d.getUTCMonth() + 1 === m &&
    d.getUTCDate() === day
  );
}

const today = new Date();
today.setUTCHours(0, 0, 0, 0);

function sevenDaysOut() {
  const d = new Date(today);
  d.setUTCDate(d.getUTCDate() + 7);
  return d.toISOString().slice(0, 10);
}

let nextFollowUpDate = agentOutput.nextFollowUpDate;
let dateWasCorrected = false;

if (!isRealDate(nextFollowUpDate)) {
  nextFollowUpDate = sevenDaysOut();
  dateWasCorrected = true;
} else if (new Date(nextFollowUpDate + 'T00:00:00Z').getTime() < today.getTime()) {
  // Also enforce "never before today" here, not just in the prompt.
  nextFollowUpDate = sevenDaysOut();
  dateWasCorrected = true;
}

return [
  {
    json: {
      ...agentOutput,
      nextFollowUpDate,
      // true means the agent's raw output was invalid or in the past and
      // got clamped to a 7-day default. Worth watching this field over
      // time — repeated corrections for the same lead type is a sign the
      // prompt needs another look, not just this safety net.
      dateWasCorrected,
    },
  },
];

