const today = new Date();
today.setUTCHours(0, 0, 0, 0);

function sevenDaysOut() {
  const d = new Date(today);
  d.setUTCDate(d.getUTCDate() + 7);
  return d.toISOString().slice(0, 10);
}

let nextFollowUpDate = agentOutput.nextFollowUpDate;
let dateWasCorrected = false;

if (!isRealDate(nextFollowUpDate)) {
  nextFollowUpDate = sevenDaysOut();
  dateWasCorrected = true;
} else if (new Date(nextFollowUpDate + 'T00:00:00Z').getTime() < today.getTime()) {
  // Also enforce "never before today" here, not just in the prompt.
  nextFollowUpDate = sevenDaysOut();
  dateWasCorrected = true;
}

return [
  {
    json: {
      ...agentOutput,
      nextFollowUpDate,
