  if (next >= MAX_FOLLOW_UPS) {
    body.takeFollowUp = false;
    action = 'exhausted';
  } else {
    body.takeFollowUp = true;
    body.nextFollowUpDate = addDays(LADDER[next] ?? 3);
    action = 'scheduled';
